COMBAT = [["/* Called only after PlayerDeath accepted the terminal transition. Preserve XP\n * in the committed player owner but do not open a level-up modal over death.\n * On failed admission the caller must cancel the still-active sequence. */\nint EspNativeGameplayMonsterCombat_commitTerminalSplashSequence(\n    uint32_t sequence) {\n    if (sequence == 0U ||\n        (splashLevelUpSequence != 0U &&\n         splashLevelUpSequence != sequence)) return 0;\n    if (!EspNativeGameplayMonsterCombat_commitSplashSequence(sequence)) return 0;\n    splashLevelUpSequence = 0U;\n    memset(&splashLevelUp, 0, sizeof(splashLevelUp));\n    return 1;\n}\n\n/* A barrel may roll back later chain waves: never play a monster sound","/* A barrel may roll back later chain waves: never play a monster sound"]]

def restore_pre_ai14_terminal_splash(current: bytes, edits) -> bytes:
    for new, old in edits:
        new, old = new.encode("utf-8"), old.encode("utf-8")
        assert current.count(new) == 1, ("A2-P1b source drift", new[:80])
        current = current.replace(new, old, 1)
    return current
